'use client';import {Printer,AlertCircle} from 'lucide-react';import {money} from '@/lib/data';import {useStore} from '@/lib/store';import {Panel,Toolbar} from '@/components/Panel';export default function Reports(){const{products,bills}=useStore();const sold=products.map(p=>{let q=0,t=0;bills.forEach(b=>b.items.forEach(i=>{if(i.productId===p.id){q+=i.qty;t+=i.total}}));return{...p,q,t}}).sort((a,b)=>b.t-a.t);return <><Toolbar title="Reports" subtitle="Sales and product performance overview"><button className="ghost-btn" onClick={()=>window.print()}><Printer/>Print Report</button></Toolbar><div className="report-grid"><Panel><h3>Top Selling Products</h3>{sold.slice(0,8).map((p,i)=><div className="bar-row" key={p.id}><span>{p.name}</span><div><i style={{width:`${Math.min(100,(p.t/(sold[0]?.t||1))*100)}%`}}/></div><b>{money(p.t)}</b></div>)}</Panel><Panel><h3>Low Stock Alerts</h3>{products.filter(p=>p.stock<8).map(p=><div className="alert-row" key={p.id}><AlertCircle/><div><b>{p.name}</b><span>Only {p.stock} left</span></div></div>)}{!products.some(p=>p.stock<8)&&<p className="empty">No low-stock products.</p>}</Panel></div></>}
